const headerClass = (deviceId, field, value, setpoint, flowRate) => {
  const reading = Number(value);
  if (!Number.isFinite(reading) || !Number.isFinite(Number(flowRate)) || Number(flowRate) <= 0) return 'neutral';

  if (field === 'deltaT') {
    if (reading < 3 || reading > 9) return 'bad';
    if (reading < 4 || reading > 7) return 'warn';
    return 'good';
  }
  if (deviceId === 'chwHeader' && field === 'supplyT') {
    const target = Number(setpoint);
    if (reading < 3 || reading > 20) return 'bad';
    if (!Number.isFinite(target)) return 'neutral';
    return Math.abs(reading - target) <= 0.1 ? 'good' : 'warn';
  }
  if (deviceId === 'chwHeader' && field === 'returnT') return reading <= 30 ? 'good' : 'bad';
  if (deviceId === 'cwHeader' && field === 'supplyT') return reading < 28.9 ? 'good' : 'warn';
  if (deviceId === 'cwHeader' && field === 'returnT') {
    if (reading > 45) return 'bad';
    return reading < 40 ? 'good' : 'warn';
  }
  return 'neutral';
};

context.handlebars.registerHelper('headerDevice', (data, deviceId, field, setpoint) => {
  const source = data.find(d => d.deviceId === deviceId);
  if (!source) return undefined;

  const d = { ...source, setpoint };
  d.supplyTClass = headerClass(deviceId, 'supplyT', d.supplyT, setpoint, d.flowRate);
  d.returnTClass = headerClass(deviceId, 'returnT', d.returnT, setpoint, d.flowRate);
  d.deltaTClass = headerClass(deviceId, 'deltaT', d.deltaT, setpoint, d.flowRate);
  d.statusClass = field ? headerClass(deviceId, field, d[field], setpoint, d.flowRate) : 'neutral';
  return d;
})

context.handlebars.registerHelper('deltaTControl', (data, deviceId, target, deadband) => {
  const source = data.find(d => d.deviceId === deviceId);
  if (!source) return undefined;

  const deltaT = Number(source.deltaT);
  const numericTarget = Number(target);
  const numericDeadband = Math.abs(Number(deadband));
  const flowRate = Number(source.flowRate);
  let statusClass = 'neutral';

  if (
    Number.isFinite(deltaT) &&
    Number.isFinite(numericTarget) &&
    Number.isFinite(numericDeadband) &&
    Number.isFinite(flowRate) &&
    flowRate > 0
  ) {
    if (deltaT < 3 || deltaT > 9) statusClass = 'bad';
    else if (deltaT < 4 || deltaT > 7) statusClass = 'warn';
    else statusClass = Math.abs(deltaT - numericTarget) <= numericDeadband ? 'good' : 'warn';
  }

  return { deltaT, target: numericTarget, deadband: numericDeadband, statusClass };
})

