context.handlebars.registerHelper("pump", (pumpId) => {
  if (!pumpId) return 'Not Assigned';
  return pumpId.toUpperCase();
});

context.handlebars.registerHelper("flowStatus", (sw, flowRate) => {
  if (sw === 1) return `<span class="chiller-package-status good">Proven</span>`;
  if (flowRate > 1 && sw == 0) return `<span class="chiller-package-status bad">Not proven</span>`;
  return `<span class="chiller-package-status neutral">Not required</span>`;
})

context.handlebars.registerHelper("state", (state) => {
  if (state === 0) return "idle";
  if (state === 1) return "starting";
  if (state === 2) return "run";
  if (state === 3) return "stopping";
  if (state === 4) return "tripped";
  return "unavailable";
})


context.handlebars.registerHelper("priority", priority => {
  if (priority === 2) return "lead";
  if (priority === 1) return "lag";
  if (priority === 0) return "standby";
  return "excluded";
})

context.handlebars.registerHelper("availability", availability => {
  if (availability === 2) return "available";
  if (availability === 1) return "maintenance";
  return "disabled";
})

context.handlebars.registerHelper("controlMode", (mode) => {
  return mode == 1 ? 'auto' : 'manual';
})

context.handlebars.registerHelper('packageThresholdClass', (metric, value, state, reference) => {
  const reading = Number(value);
  if (Number(state) !== 2 || !Number.isFinite(reading)) return 'neutral';

  if (metric === 'efficiency') {
    if (reading <= 0 || reading > 0.780) return reading <= 0 ? 'neutral' : 'bad';
    return reading <= 0.715 ? 'good' : 'warn';
  }
  if (metric === 'evapLWT') {
    const setpoint = Number(reference);
    if (reading < 3 || reading > 20) return 'bad';
    if (!Number.isFinite(setpoint)) return 'neutral';
    return Math.abs(reading - setpoint) <= 0.1 ? 'good' : 'warn';
  }
  if (metric === 'evapEWT') return reading <= 30 ? 'good' : 'bad';
  if (metric === 'condEWT') return reading < 28.9 ? 'good' : 'warn';
  if (metric === 'condLWT') {
    if (reading > 45) return 'bad';
    return reading < 40 ? 'good' : 'warn';
  }
  if (metric === 'deltaT') {
    if (reading < 3 || reading > 9) return 'bad';
    if (reading < 4 || reading > 7) return 'warn';
    return 'good';
  }
  return 'neutral';
});

context.handlebars.registerHelper('device', (data, deviceId) => {
  return data.find(d => d.deviceId === deviceId);
})

context.handlebars.registerHelper('runHours', runtimeSec => {
  return Math.floor(runtimeSec / 3600);
})

context.handlebars.registerHelper('runTime', runtime => {
  const hour = Math.floor(runtime / 60);
  const min = Math.round(runtime % 60);
  return `${hour}h ${min}m`
})

context.handlebars.registerHelper('toUpperCase', (str) => str?.toUpperCase() ?? '---');

context.handlebars.registerHelper('length', (data) => data.length);


context.handlebars.registerHelper('sum', (data, field) => {
  return data.reduce((acc, d) => acc + d[field], 0);
})

context.handlebars.registerHelper('divide', (a, b) => a / b)

context.handlebars.registerHelper('numberFormat', function (value, options) {
  // Helper parameters
  var dl = options.hash['decimalLength'];
  if (dl == null) {
    dl = 2;
  }
  var ts = options.hash['thousandsSep'] || ',';
  var ds = options.hash['decimalSep'] || '.';

  // Parse to float
  var value = parseFloat(value);

  // The regex
  var re = '\\d(?=(\\d{3})+' + (dl > 0 ? '\\D' : '$') + ')';

  // Formats the number with the decimals
  var num = value.toFixed(Math.max(0, ~~dl));

  // Returns the formatted number
  return (ds ? num.replace('.', ds) : num).replace(new RegExp(re, 'g'), '$&' + ts);
});

context.handlebars.registerHelper('activeStatus', (running, target) => {
  if (running < target) return 'bad'
  if (running > target) return 'warn'
  return 'good'

});

// Theme class: 'dark' or 'light' based on the viewer's Grafana theme
context.handlebars.registerHelper('themeClass', () => {
  const theme = context.grafana && context.grafana.theme;
  if (theme) return theme.isDark ? 'dark' : 'light';
  return document.body.classList.contains('theme-light') ? 'light' : 'dark';
});

