    if (reading >= 1048) return 'bad';
    return reading >= 943 ? 'warn' : 'good';
  }
  if (metric === 'evapSatTemp') {
    if (Number.isFinite(reference) && reference < 0) return 'special';
    if (reading <= 1.1) return 'bad';
    return reading <= 3 ? 'warn' : 'good';
