    return Number.isFinite(reference) && reading < reference ? 'special' : 'neutral';
  }
  if (metric === 'dischargeTemp') {
    if (Number.isFinite(reference) && reading < reference) return 'special';
    if (reading >= 88) return 'bad';
    return reading >= 77 ? 'warn' : 'good';
  }
  if (metric === 'approach') {
    if (reading < 0) return 'special';
    if (reading >= 2.7) return 'bad';
    return reading > 0.8 ? 'warn' : 'good';
  }
  return 'neutral';
});
