  text-transform: uppercase;
}
.chiller-detail-value {
  margin-top: 3px;
  font-size: 18px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.chiller-detail-unit,
.chiller-detail-subvalue {
  color: var(--color-text-secondary, #667085);
  font-size: 12px;
  font-weight: 400;
}
.chiller-detail-good {
  color: #548235;
}
.chiller-detail-warn {
  color: #92400e;
}
.chiller-detail-bad {
  color: #c00000;
}
.chiller-detail-special {
  color: #2563eb;
}
.chiller-detail-neutral {
  color: var(--color-text-primary, #1f2933);
}
.chiller-detail-status {
  display: inline-block;
  padding: 2px 6px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.3px;
  text-transform: uppercase;
}
.chiller-detail-status.good,
.chiller-detail-status.run {
  color: #166534;
  background: #dcfce7;
}
.chiller-detail-status.idle {
  color: #667085;
  background: #f2f4f7;
}
.chiller-detail-status.unassigned {
  color: #667085;
  background: #eaecf0;
}
.chiller-detail-status.trip,
.chiller-detail-status.tripped {
  color: #991b1b;
  background: #fee2e2;
}
.chiller-detail-compressors,
.chiller-detail-pumps {
  display: grid;
  gap: 12px;
  margin-top: 8px;
}
.chiller-detail-compressors {
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
}
.chiller-detail-pumps {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.chiller-detail-compressor,
.chiller-detail-pump {
  min-width: 0;
  padding: 10px;
  border: 1px solid #d0d5dd;
  border-radius: 4px;
}
.chiller-detail-compressor.run,
.chiller-detail-pump.run {
  background: #f7fbf4;
  border-color: #d9ead3;
}
.chiller-detail-compressor.idle,
.chiller-detail-pump.idle {
  background: #f8fafc;
}
.chiller-detail-pump.unassigned {
  background: #f8fafc;
  border-style: dashed;
}
.chiller-detail-pump.trip,
.chiller-detail-pump.tripped {
  background: #fef2f2;
  border-color: #fecaca;
}
.chiller-detail-compressor-head,
.chiller-detail-pump-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 14px;
  font-weight: 700;
}
.chiller-detail-compressor-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0 12px;
  margin-top: 6px;
}
.chiller-detail-pump-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0 12px;
  margin-top: 6px;
}
.chiller-detail-compressor .chiller-detail-metric {
  padding: 6px 0;
}
.chiller-detail-compressor .chiller-detail-value {
  font-size: 14px;
}
@media (max-width: 700px) {
  .chiller-detail-grid,
  .chiller-detail-compressors,
  .chiller-detail-pumps {
    grid-template-columns: 1fr;
  }
}

